class BIT {
    vector<int> tree;
    int n;
public:
    BIT(int n) : n(n) { tree.resize(n + 1, 0); }
    void add(int i, int delta) {
        for (; i <= n; i += i & -i) tree[i] += delta;
    }
    int query(int i) {
        int sum = 0;
        for (; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }
};

int countInversions(vector<int>& arr) {
    int n = arr.size();
    vector<int> temp = arr;
    sort(temp.begin(), temp.end());
    for(int i=0; i<n; i++) {
        arr[i] = lower_bound(temp.begin(), temp.end(), arr[i]) - temp.begin() + 1;
    }
    BIT bit(n);
    int inv = 0;
    for(int i = n - 1; i >= 0; i--) {
        inv += bit.query(arr[i] - 1);
        bit.add(arr[i], 1);
    }
    return inv;
}
